{v:'VER',what:'his order 2026-10-15 (one score name): the running score tile of a CAREER raid reads RAID SCORE, the name the run card ledger and the leaderboard use, not CAREER SCORE',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__runPrep&&window.__resetCfg&&window.__pinDefaults)||typeof raidStatusDraw!=='function') return 'SKIP: no raid status here';
   var bad=[], g=null, car0, cs0, L, i, hit=0, old=0, amt=0;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0);
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     if(g.arcade) return 'SKIP: an arcade raid has its own score tile';
     car0=g.career; cs0=g.cs; g.career=true; g.cs={s:1234};
     raidStatusDraw();
     L=(typeof RSTAT==='object'&&RSTAT&&RSTAT.lines)||[];
     for(i=0;i<L.length;i++){ if(/^RAID SCORE$/.test(L[i])) hit++; if(/^CAREER SCORE$/.test(L[i])) old++; if(/^\$1,234$/.test(L[i])) amt++; }
     if(!hit) bad.push('the career score tile does not read RAID SCORE ('+L.slice(0,8).join(' | ')+')');
     if(old) bad.push('the career score tile still reads CAREER SCORE');
     if(!amt) bad.push('the tile does not carry the score $1,234');
     g.career=car0; g.cs=cs0;
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{
     try{ if(g){ g.career=car0; g.cs=cs0; } }catch(_c){}
     try{ var g2=__state(); if(g2&&!g2.over){ g2.player.iv=0; __endRaid('abandon'); } }catch(_e){}
     __topClear(); }
   return bad.length?bad.join('; '):null; }},
